syntax:
label_name:           // a label: any name, then a colon
    statement;

goto label_name;      // jump to the label (same function only)

// backward jump (makes a loop):
again:
    // ... code ...
    if (condition) goto again;

// forward jump (skips code):
    if (problem) goto cleanup;
    // ... skipped when problem is true ...
cleanup:
    // ... code continues here ...

sample.code:
#include <iostream>
using namespace std;

int main() {
    int i = 1;
start:
    cout << i << " ";
    i++;
    if (i <= 5) {
        goto start;
    }
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 3; i++) {
        for (int j = 1; j <= 3; j++) {
            if (i * j == 6) {
                cout << "Found: " << i << " x " << j << endl;
                goto done;
            }
        }
    }
    cout << "Not found" << endl;
done:
    cout << "Search finished" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    bool found = false;
    int checks = 0;
    for (int i = 1; i <= 3 && !found; i++) {
        for (int j = 1; j <= 3 && !found; j++) {
            checks++;
            if (i * j == 6) {
                cout << "Found: " << i << " x " << j << endl;
                found = true;
            }
        }
    }
    if (!found) {
        cout << "Not found" << endl;
    }
    cout << "Checks: " << checks << endl;
    return 0;
}

